     "why": "本鄉心裡期待協理驗收譯文，信裡卻只寫「屆時您可確認內容」，沒有表明這是請求，也沒有期限，結尾仍是「謹向您報告」。協理只能回問「我要負責驗收嗎？什麼時候前？」，或乾脆置之不理。先把主題拆成「報告＋請求」兩個提問、各自得出So What，請求與期限就不會漏寫。技巧：**以提問呈現主題**、**期待的回應**。改後的郵件把兩個答案各做成一個「●」區塊，先寫結論句、再列理由或步驟，請求也附上明確時刻（7日17時左右驗收、8日9時前指示修改）。"
