     "title": "例題 3-1【引言】業務改善專案",
     "before": "出差行程奔波勞頓，您辛苦了。\n關於業務改善專案的啟動時機，今天室町協理已與專案行政小組進行評估。\n經評估後，我們認為專案的啟動時間，應該安排在上半年度關帳後，也就是10月。……\n與會成員一致認為，目前專案預計依原訂計畫於10月啟動，不會提前開始。\n以上報告。",
     "after": "出差行程奔波勞頓，您辛苦了。\n關於業務改善專案的啟動時間事宜，向您報告今日室町協理與專案行政小組評估的結果。懇請不吝確認。\n（評估結果與理由，移到引言之後的正文）",
