     "before": "本次語音郵件改版更新之際，包括召開部內說明會等業務，承蒙各位長官多方包涵，感謝各位配合。\n本部門已製作「新版語音郵件FAQ集」，並於上週公布在公司的內部網站上。\n這份FAQ集匯整同仁們在新版語音郵件導入前所舉辦的研習課程當中，實際提出的問題與解答。\n然而，各部門同仁還是紛紛打電話諮詢……（中略）\n因此，懇請各部門配合，多加利用FAQ集。",
     "after": "本次語音郵件改版更新之際，包括召開部內說明會等業務，承蒙各位長官多方包涵，感謝各位配合。本部門已製作「新版語音郵件FAQ集」，並於上週公布在公司的內部網站上。**懇請各位協助宣導，鼓勵部屬多加利用FAQ集。**",
     "why": "問候及格，但之後只寫背景，主題「懇請多加利用FAQ集」與期待的回應「鼓勵部屬多加利用」到信末才模糊出現。這是「先背景、後請求」的常見陷阱，對象愈忙、地位愈高，傷害愈大。只要在背景後追加一句，就把引言變成「速度取向」，也展現對收訊者時間的尊重。"
