     "after": "您好，又到製作阿爾發學院課程大綱的時期。\n我製作課程大綱格式的改版草案，在此向您提案。\n若能於本週內同意，我將不勝感激。",
     "why": "短信也要有引言的基本形式。原信沒有主題「格式改版提案」，也沒有期待的回應「核准草案」，更沒有關鍵的期限。改寫後主題、期待的回應、日期一次到位；「若能於本週內同意，我將不勝感激」以委婉語氣告知期限，避免強硬，目標是一次往返就拍板。"
