     "after": "【結構方格（原書參考解答圖）】\n提問：希望語音郵件的使用者做什麼事？\n　↕\n結論：希望大家在打電話諮詢前，先看看FAQ集。\n第二層（切入點＝對比概念「效率／效果」，彰顯對使用者的好處）\n　［節省大家的時間］電話諮詢量龐大，以致電話很難接通。來電諮詢的問題當中，多數其實都已收錄在FAQ集裡。只要在打電話前瀏覽一下，就能節省大家的時間。\n　［提供更優質的協助］由於電話諮詢量龐大，本部門沒有充裕時間仔細回答每個問題。若能妥善運用FAQ集，減少來電數量，我們就能提供更優質的協助。\n\n【書末附錄完成版（節錄）】\n懇請各位在撥打電話前，務必先閱讀FAQ集。\n為了節省大家的時間：電話諮詢量龐大，以致電話很難接通。只要在打電話前瀏覽一下FAQ集，就能節省大家的時間。\n為了提供更優質的協助：由於電話諮詢量龐大，本部門沒有充裕時間仔細回答每個問題。若能妥善運用FAQ集，減少來電數量，我們就能提供更優質的協助。",
     "why": "原文把理由逐條堆疊。改寫先選對結論：B「打電話前先利用FAQ」比A「多加利用FAQ」更能寫出請求重點，不會只是重述引言。再以「目的取向」找切入點——從使用者的好處出發，用效率／效果這組對比概念分類，最後依課程6把好處寫成完整句子、不擅自省略。（解說中的候選B寫作「希望大家在打電話洽詢前，先多加利用FAQ集」，參考解答圖定稿為「先看看FAQ集」。）"
