     "title": "實戰練習4-5 內部表單傳送（總務部 半澤愛）",
     "before": "（實戰練習3-5的原郵件正文）\n近來內部傳送表單填寫缺漏的情況日益增加，導致發送前需要多花時間確認文件物品要送交到哪一個部門。\n其中又以總公司傳送到各營業處的文件物品，漏填部門名稱的情況特別嚴重。此外，自上個月起，本業務新增一位新進的計時人員協助處理，如果表單填寫不正確，就要耗費更多時間處理分送。\n\n〔題目給的結構方格（實戰練習3-5，原書圖）〕\n提問：希望內部傳送機制的使用者做什麼？\n結論：想請同仁正確填寫內部傳送表單的寄件人、收件人的姓名與部門名稱\n　├使用者的問題：近來內部傳送表單填寫缺漏的情況日益增加。其中又以總公司傳送到各營業處的文件物品，漏填部門名稱的情況特別嚴重\n　└承辦人的問題：本項業務承辦人員已加強確認有無填寫缺漏情形，但由於本業務新增一位計時人員，故在確認上需花費較長時間，連帶也使得於傳送文件、材料的時間變久",
     "after": "（附錄解答；縮排依本章規則呈現）\n主旨：關於內部傳送的請求事宜\n各位使用內部傳送機制的同仁大家好：\n為了讓各項文件、材料能透過內部傳送機制迅速配送，在使用內部傳送系統時，懇請配合以下事項：\n〔空一行〕\n●請求配合事項\n請務必正確填寫內部傳送表單的收件人欄位，切勿缺漏。\n　　．近來內部傳送表單填寫缺漏的情況，日益增加；\n　　．其中又以總公司傳送到各營業處的文件物品，漏填部門名稱的情況特別嚴重；\n　　．本項業務承辦人員已加強確認有無填寫缺漏情形，但由於本業務新增一位計時人員，在確認上需花費較長時間，連帶也使得傳送文件、材料的時間變久。\n〔空一行〕\n懇請各位包涵，並配合確實填寫單據，謝謝各位。\n總務部 半澤愛",
     "why": "原文只描述現象（缺漏增加、營業處特別嚴重、新增計時人員），真正的請求「正確填寫收件人欄位」從頭到尾沒有明說，讀者得自己推論。改寫：主旨標明「請求」；引言說明目的並預告「懇請配合以下事項」；「●請求配合事項」底下先寫結論（具體要做什麼），再用三個「．」列出理由——整體現況→特別嚴重之處→處理端的限制，形成由大到小、由現象到影響的排列。對照方格：前兩個「・」是第二層「使用者的問題」拆成兩點，第三個「・」對應「承辦人的問題」。"
