     "title": "實戰練習4-6 其他商務書信（以實戰練習3-6 電話系統轉換為例）",
     "before": "（實戰練習3-6原文，節錄）\n公司自4月10日(一)起，將轉換為新的電話系統。謹在此針對可能遇見的諮詢問題，報告相關因應方案。……\n預估下列事項之相關諮詢將會大增。\n1 新話機操作、功能之相關事項\n2 更新後的語音郵件之相關事項\n支援服務中心會受理「1」和「2」的諮詢。另外，我們將於3月20日向全體同仁布達，基本資訊可參閱……「操作手冊」和「FAQ」。\n至於「2」的部分，……預估諮詢內容應該主要會在這方面。具體而言，就是防止誤傳訊息等功能。……\n因此，自10日(一)至21日(五)的上班時間內，會增派一名人手到支援服務中心。\n此外，後續將根據諮詢內容修訂FAQ。",
     "after": "（附錄解答正文節錄；縮排依本章規則呈現）\n●預期可能接到的諮詢\n大致可分為兩種，但預估應該是以語音郵件的相關問題為大宗：\n　　1 在語音郵件方面，又以「防止誤傳訊息功能的設定」居多；\n　　2 其他則是新話機操作、功能的相關事項。\n●因應方案\n除了加強宣導操作手冊、FAQ的運用之外，支援服務中心也會針對語音郵件提供個別諮詢服務。\n　　．**落實運用FAQ集等工具**\n　　　我們會事先向所有經理級主管布達，請同仁多加利用操作手冊和FAQ集，查詢「1」和「2」的基本資訊（預計於3/20(一)發送）。\n　　．**轉換初期強化支援服務中心**\n　　　4/10(一)～4/21(五)的核心上班時間，會加派一名人力到支援服務中心，提供以「1」為主的個別諮詢。\n　　．**FAQ集改版升級**\n　　　後續將根據諮詢內容修訂FAQ。",
     "why": "原文把兩個提問（會有哪些諮詢？怎麼因應？）的答案交錯在一起，「語音郵件是大宗」這個重點藏在中段。改寫成兩組結構方格：「●預期可能接到的諮詢」先寫So What（分兩種、以語音郵件為大宗），並把語音郵件調到第1項；「●因應方案」先總述結論，再用「．」列出三個切入點，依時間步驟排列：轉換前（布達FAQ）→轉換初期（加派人力）→後續（FAQ改版）。"
