     "before": "主旨：QC頒獎典禮前晚住宿事宜\n參加QC頒獎典禮的同仁您好：\n日前已公布2017年度的QC活動頒獎典禮，將於下週24日（一）9:00起，在總公司大會議室舉行。\n・請於23日（日）23點前進入東都研修所。由於門禁時間為23點，逾時將無法入館；\n・23日（日）請先用晚餐再入館，或帶進研修所內餐廳用餐；\n・24日（一）也請自理早餐後，至總公司集合。\n→研修所不供餐。\n【應備物品】……\n※參考資訊（至總公司交通方式）……\n→共約40分鐘。早上尖峰時段電車經常誤點，請預留交通時間。",
